//! 仅用于隔离基准构建的相同测量协议。
use std::{sync::{Mutex, atomic::{AtomicBool, Ordering}}, time::Instant};
use tauri::Manager;
pub(crate) struct NativeBenchmark { pub started: Instant, pub ready: AtomicBool, pub samples: Mutex<Vec<f64>> }
#[tauri::command]
pub(crate) fn native_benchmark_ping() -> bool { true }
#[tauri::command]
pub(crate) fn native_benchmark_ready<R: tauri::Runtime>(app: tauri::AppHandle<R>, state: tauri::State<'_, NativeBenchmark>) -> Result<(), String> {
 let first = !state.ready.swap(true, Ordering::AcqRel);
 if !first { return Ok(()); }
 let startup_ms = state.started.elapsed().as_secs_f64()*1000.;
 let path=app.path().app_data_dir().map_err(|_| "benchmark path")?.join("native-benchmark.json");
 let report=serde_json::json!({"pid":std::process::id(),"startup_ms":startup_ms,"ipc_ms":state.samples.lock().map_err(|_| "benchmark lock")?.clone()});
 std::fs::write(path,serde_json::to_vec_pretty(&report).map_err(|_| "benchmark encoding")?).map_err(|_| "benchmark write".to_string())
}
#[tauri::command]
pub(crate) fn native_benchmark_ipc_samples<R: tauri::Runtime>(app: tauri::AppHandle<R>, _state: tauri::State<'_, NativeBenchmark>, samples: Vec<f64>) -> Result<(), String> {
 if samples.len()!=200 || samples.iter().any(|x| !x.is_finite() || *x < 0.) {return Err("invalid benchmark samples".into());}
 let path=app.path().app_data_dir().map_err(|_| "benchmark path")?.join("native-benchmark.json");
 let mut report:serde_json::Value=serde_json::from_slice(&std::fs::read(&path).map_err(|_| "benchmark read")?).map_err(|_| "benchmark decode")?;
 report["ipc_ms"]=serde_json::json!(samples);
 std::fs::write(path,serde_json::to_vec_pretty(&report).map_err(|_| "benchmark encoding")?).map_err(|_| "benchmark write".to_string())
}

