import { invoke } from "@tauri-apps/api/core";
export function scheduleNativeBenchmark(): () => void {
 let canceled=false; let frame=0;
 frame=requestAnimationFrame(()=>{frame=requestAnimationFrame(()=>{void (async()=>{
  if(canceled)return;
  await invoke("native_benchmark_ready");
  const samples:number[]=[];
  for(let i=0;i<220;i++){const start=performance.now();await invoke("native_benchmark_ping");if(i>=20)samples.push(performance.now()-start);}
  await invoke("native_benchmark_ipc_samples",{samples});
 })();});});
 return ()=>{canceled=true;cancelAnimationFrame(frame);};
}
